      var index = this.activeBgIndex;
      var len = this.nsrsbhList.length;
      //38:上  40:下
      if (e.keyCode == 38) {
        if (index > 0) {
          index--;
        } else {
          index = len - 1;
        }
        this.stopDefault(e);
      } else if (e.keyCode == 40) {
        if (index < len - 1) {
          index++;
        } else {
          index = 0;
        }
        this.stopDefault(e);
      }
      this.activeBgIndex = index;
