      form.attr("style", "display:none");
      form.attr("target", "hiddenframe");
      // form.attr("target", "_blank")
      form.attr("method", "post");
      form.attr("action", "/cxfw/fxgl/hdtj/export");
      var input1 = $("<input>");
      input1.attr("type", "hidden");
