    //copy
    initTree: function initTree() {
      var self = this;
      var setting = {
        callback: {
          onClick: function onClick(e, id, node) {
            self.searchData.zgswjgks = node.id;
            self.tsjgmc = node.text;
            self.hideTree();
            return;
          },
          onDblClick: function onDblClick(e, id, node) {
            self.searchData.zgswjgks = node.id;
            self.tsjgmc = node.text;
            self.hideTree();
            return;
          }
        },
        data: { key: { children: "item", name: "text" } }
      };
      ajax("POST", "/cxfw/export/readtree", { nodeType: "4" }).done(function (res) {
        if (res.code == '0') {
          var data = self.replaceEmptyItemWithNull(res.data);
          $.fn.zTree.init($(".shmxcx #shmxcxtree"), setting, data);
        } else {
          tools.info(res.msg);
        }
      }).fail(function (err) {
        tools.info(err);
      });
    },
    initTreeTuishui: function initTreeTuishui() {
      var self = this;
      var setting = {
        callback: {
          onClick: function onClick(e, id, node) {
            self.searchData.swjgDm = node.id;
            self.swjgMc = node.text;
            self.hideTree();
            return;
          },
          onDblClick: function onDblClick(e, id, node) {
            self.searchData.swjgDm = node.id;
            self.swjgMc = node.text;
            self.hideTree();
            return;
          }
        },
        data: { key: { children: "item", name: "text" } }
      };
      ajax("POST", "/cxfw/export/readtree", { nodeType: "3" }).done(function (res) {
        if (res.code == "0") {
          var data = self.replaceEmptyItemWithNull(res.data);
          $.fn.zTree.init($(".shmxcx #shmxcxtreeTs"), setting, data);
          if (data.length) {
            self.swjgMc = data[0].text;
            self.firstSwjgMc = data[0].text;
            self.firstSwjgdm = data[0].id;
            self.searchData.swjgDm = data[0].id;
          }
        } else {
          tools.info(res.msg);
        }
      }).fail(function (err) {
        tools.info(err);
      });
    },
