module.exports = "<div class=\"fxfxbg\">\r\n  <div class=\"form\" style=\"padding-top: 0;background: #fff;\">\r\n    <!-- 顶部信息栏 -->\r\n    <div class=\"fxfxbg-header\" style=\"padding: 5px 20px; background: #fff; border-bottom: 1px solid #e4e7ed;\">\r\n      <div style=\"display: flex; align-items: center; justify-content: space-between;\">\r\n        <div style=\"flex: 1;\">\r\n          <span style=\"font-size: 14px; font-weight: bold;\">\r\n            <span style=\"color: #e04957;\">{{@nsrmc}}（{{@nsrsbh}}）{{@atfxrqqz}}</span>\r\n            <span ms-if=\"@reportData.ztbz == '' || @reportData.ztbz == '10'\" style=\"color: #e04957; margin-left: 5px;\">（未生成）</span>\r\n            <span ms-if=\"@reportData.ztbz == '2'\" style=\"color: #e04957; margin-left: 5px;\">\r\n              （已生成）\r\n              <span ms-if=\"@reportData.clkssj\" style=\"color: #909399;\">处理时间：{{@reportData.clkssj}}</span>\r\n              <span ms-if=\"@reportData.clwcsj\" style=\"color: #909399; margin-left: 10px;\">完成时间：{{@reportData.clwcsj}}</span>\r\n            </span>\r\n            <span ms-if=\"@reportData.ztbz != '' && @reportData.ztbz != '10' && @reportData.ztbz != '2' && @reportData.ztbz != '9'\" style=\"color: #e04957; margin-left: 5px;\">\r\n              （处理中）\r\n              <span ms-if=\"@reportData.clkssj\" style=\"color: #909399;\">处理时间：{{@reportData.clkssj}}</span>\r\n              <span ms-if=\"@reportData.clwcsj\" style=\"color: #909399; margin-left: 10px;\">完成时间：{{@reportData.clwcsj}}</span>\r\n            </span>\r\n            <span ms-if=\"@reportData.ztbz == '9'\" style=\"color: #e04957; margin-left: 5px;\">\r\n              （处理异常）\r\n              <span ms-if=\"@reportData.clkssj\" style=\"color: #909399;\">处理时间：{{@reportData.clkssj}}</span>\r\n              <span ms-if=\"@reportData.clwcsj\" style=\"color: #909399; margin-left: 10px;\">完成时间：{{@reportData.clwcsj}}</span>\r\n            </span>\r\n          </span>\r\n        </div>\r\n        <div style=\"display: flex; gap: 10px;\">\r\n          <!-- 未生成或处理异常状态：显示生成报告按钮 -->\r\n          <div ms-if=\"@reportData.ztbz == '' || @reportData.ztbz == '10' || @reportData.ztbz == '9'\" \r\n               class=\"btn\" \r\n               ms-click=\"@generateReport\"\r\n               style=\"float: none; display: inline-block; cursor: pointer;\" \r\n               title=\"生成报告\">\r\n            生成报告\r\n          </div>\r\n          <!-- 已生成状态：显示下载word报告按钮 -->\r\n          <div ms-if=\"@reportData.ztbz == '2'\" \r\n               class=\"btn\" \r\n               ms-click=\"@downloadReport\"\r\n               style=\"float: none; display: inline-block; cursor: pointer;\" \r\n               title=\"下载word报告\">\r\n            下载word报告\r\n          </div>\r\n          <!-- 处理中状态：显示下载word报告按钮（灰色不可点击）+ 刷新按钮 -->\r\n          <div ms-if=\"@reportData.ztbz != '' && @reportData.ztbz != '10' && @reportData.ztbz != '2' && @reportData.ztbz != '9'\" style=\"display: flex; gap: 10px; align-items: center;\">\r\n            <div class=\"btn disabled\" \r\n                 style=\"float: none; display: inline-block;\" \r\n                 title=\"下载word报告\">\r\n              下载word报告\r\n            </div>\r\n            <div class=\"btn\" \r\n                 ms-click=\"@refreshStatus\"\r\n                 style=\"float: none; display: inline-block; cursor: pointer; padding: 2px 8px;\" \r\n                 title=\"刷新状态\">\r\n              <i class=\"fa fa-refresh\" style=\"margin-right: 4px;\"></i>刷新\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    \r\n    <!-- PDF预览区域 -->\r\n    <div class=\"fxfxbg-content\" style=\"height: calc(100vh - 190px); overflow-y: auto;padding: 0 5px;\">\r\n      <div style=\"box-sizing: border-box;background: #fff;  height: 99%;\">\r\n        <div id=\"pdfViewer\" style=\"width: 100%; height: 100%;\">\r\n          <!-- 未生成状态：显示空占位 -->\r\n          <div ms-if=\"@reportData.ztbz == '' || @reportData.ztbz == '10'\" style=\"text-align: center; padding: 150px 0; color: #909399;\">\r\n            <i class=\"fa fa-file-pdf-o\" style=\"font-size: 80px; margin-bottom: 20px; color: #c0c4cc;\"></i>\r\n            <p style=\"font-size: 16px; margin: 10px 0;\">报告尚未生成</p>\r\n            <p style=\"font-size: 14px; margin: 10px 0;\">请点击右上角\"生成报告\"按钮生成风险分析报告</p>\r\n          </div>\r\n          <!-- 处理中状态：显示处理中占位 -->\r\n          <div ms-if=\"@reportData.ztbz != '' && @reportData.ztbz != '10' && @reportData.ztbz != '2' && @reportData.ztbz != '9'\" style=\"text-align: center; padding: 150px 0; color: #909399;\">\r\n            <i class=\"fa fa-spinner fa-spin\" style=\"font-size: 80px; margin-bottom: 20px; color: #E6A23C;\"></i>\r\n            <p style=\"font-size: 16px; margin: 10px 0;\">报告生成中</p>\r\n            <p style=\"font-size: 14px; margin: 10px 0;\">报告正在生成中，请稍后查看...</p>\r\n          </div>\r\n          <!-- 处理异常状态：显示异常占位 -->\r\n          <div ms-if=\"@reportData.ztbz == '9'\" style=\"text-align: center; padding: 150px 0; color: #909399;\">\r\n            <i class=\"fa fa-exclamation-triangle\" style=\"font-size: 80px; margin-bottom: 20px; color: #F56C6C;\"></i>\r\n            <p style=\"font-size: 16px; margin: 10px 0;\">报告生成异常</p>\r\n            <p style=\"font-size: 14px; margin: 10px 0;\">报告生成失败，请重新尝试生成</p>\r\n          </div>\r\n          <!-- 已生成状态：显示PDF预览 -->\r\n          <div ms-if=\"@reportData.ztbz == '2'\" style=\"width: 100%; height: 100%;\">\r\n            <div id=\"pdfReportContainer\" style=\"width: 100%; height: 100%;\"></div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n";

